'use strict';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let curriculum,stage,user=null,sessionConfig={},revision=0,view='choose',activeDay=1,editorTab='blocks',mobileView='lesson',saveTimer,saveBusy=false,dirty=false,savingConflict=false;
let state={schema:1,path:null,theme:'royal',avatar:0,completed:{},checks:{},notes:{},projects:{},lastDays:{},keep:false,school:false};
let childAvatar=0;
const avatarNames=['Fox','Owl','Rabbit','Cat','Dog','Panda','Frog','Axolotl','Turtle','Penguin','Dolphin','Unicorn','Dragon','Princess','Prince','Knight','Fairy','Wizard','Astronaut','Robot','Alien','Rocket','Moon','Star','Ghost','Pumpkin','Bat','Witch cat','Monster','Mushroom'];
function avatar(n,size=80){return `<span class="avatar ${size<60?'small':''}" data-avatar="${n}" style="${PQC.avatarStyle(n,size)}" role="img" aria-label="${esc(avatarNames[n])}"></span>`;}
function fitAvatars(){document.querySelectorAll('[data-avatar]').forEach(el=>{const size=el.getBoundingClientRect().width;const style=PQC.avatarStyle(+el.dataset.avatar,size);el.style.cssText=style;});}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('visible'),4500);}
async function api(path,body,method='POST'){if(window.PQC_OFFLINE){if(path==='session')return {user:null,openChildSignup:false,parentSignup:false,inviteRequired:false};throw Error('Online accounts are available in the hosted edition. You can use all guest lessons here.');}const r=await fetch('/api/'+path,{method:body===undefined?'GET':method,headers:body===undefined?{}:{'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body),credentials:'same-origin'});let data;try{data=await r.json();}catch{throw Error('Online saving is unavailable here. Guest lessons still work.');}if(!r.ok){const e=Error(data.error||'Try again.');e.status=r.status;throw e;}return data;}
function storageWrite(store,key,value){try{store.setItem(key,JSON.stringify(value));return true;}catch{return false;}}
function persist(){
 if(user?.role==='child')keepChildDraft();
 if(state.school&&!user){try{sessionStorage.removeItem('pqc-guest');}catch{}}else if(!user)storageWrite(sessionStorage,'pqc-guest',state);
 if(state.keep&&!state.school&&!user)storageWrite(localStorage,'pqc-guest',state);
 if(user&&user.role==='child'&&!savingConflict){dirty=true;keepChildDraft();clearTimeout(saveTimer);saveTimer=setTimeout(saveOnline,1000);}
}
function keepChildDraft(){if(user?.role==='child')storageWrite(sessionStorage,'pqc-'+user.id,{payload:state,revision,dirty});}
async function saveOnline(){if(!user||user.role!=='child'||savingConflict)return;if(saveBusy){dirty=true;return;}saveBusy=true;dirty=false;
 try{const r=await api('save',{payload:state,revision});revision=r.revision;setSaveStatus('Saved online');}catch(e){dirty=true;if(e.status===409){savingConflict=true;setSaveStatus('Newer online version. Download this draft, then load online.',true);}else setSaveStatus('Not synced yet · draft kept in this browser',true);}finally{saveBusy=false;keepChildDraft();if(dirty&&!savingConflict){clearTimeout(saveTimer);saveTimer=setTimeout(saveOnline,5000);}}
}
function setSaveStatus(text,error=false){const el=$('#save-status');if(el){el.textContent=text;el.className='status'+(error?' error':'');}}
function lesson(){return curriculum.lessons.find(l=>l.path===state.path&&l.day===activeDay);}
function project(){if(!state.projects[state.path])state.projects[state.path]=PQC.defaultProject(state.theme);return state.projects[state.path];}
function pathInfo(){return curriculum.paths[state.path];}
function themeCards(){return `<div class="theme-row" aria-label="Choose a project theme">${Object.entries(PQC.THEMES).map(([key,t])=>`<button class="theme-card ${state.theme===key?'active':''}" data-action="theme" data-value="${key}" aria-pressed="${state.theme===key}"><img src="${t.file}" alt="" loading="lazy"><span>${t.name}</span></button>`).join('')}</div>`;}
function themeIntro(){return {royal:'Royal Castle quests',space:'Space Adventure quests',halloween:'Halloween quests'}[state.theme];}
function render(){stage?.destroy();stage=null;
 const main=$('#main');main.innerHTML=view==='choose'?chooseHTML():view==='month'?monthHTML():view==='lesson'?lessonHTML():view==='parents'?parentsHTML():view==='showcase'?showcaseHTML():helpHTML();
 document.body.dataset.theme=state.theme;$('#identity').textContent=user?`${user.username} · ${user.role==='parent'?'grown-up account':'saved account'}`:`Guest · ${state.school?'shared-computer mode':state.keep?'saved on this device':'temporary session'}`;
 fitAvatars();if(view==='lesson')mountLesson();if(view==='parents')loadChildren();window.scrollTo(0,0);
}
function chooseHTML(){return `<div class="intro"><div><div class="eyebrow">October 2026 · Choose your adventure</div><h1>What would you like to make?</h1><p class="muted">Choose a path that feels right. Suggested ages are a guide—you can change paths whenever you like.</p></div>${avatar(state.avatar)}</div><div class="paths">${Object.entries(curriculum.paths).map(([key,p])=>`<button class="path-card" data-action="path" data-value="${key}">${avatar(p.avatar)}<h2>${p.name}</h2><span class="age">${p.ages}</span><p>${p.summary}</p><span class="pill">${p.time} per quest</span></button>`).join('')}</div><h2>Choose your world</h2>${themeCards()}<p class="meta">Start as a guest. No name, birthday or email needed to try a lesson.</p><div class="toolbar"><button data-action="local-settings">Saving on this device</button><button data-action="account">Sign in to a saved account</button></div>`;}
function completedCount(path=state.path){return Object.entries(state.completed).filter(([id,v])=>id.startsWith(path+'-')&&v).length;}
function monthHTML(){const p=pathInfo(),count=completedCount();let cells='<div class="empty-day"></div>'.repeat(4);for(let d=1;d<=30;d++){const l=curriculum.lessons.find(l=>l.path===state.path&&l.day===d);cells+=`<button class="day ${state.completed[l.id]?'done':''} ${state.lastDays[state.path]===d?'current':''}" data-action="day" data-value="${d}" aria-label="October ${d}: ${esc(l.title)}${state.completed[l.id]?', completed':''}"><strong>${d}${state.completed[l.id]?' ✓':''}</strong><span class="day-title">${esc(l.title)}</span><span class="meta">${l.mode==='browser'?'Here':l.mode==='scratch'?'Scratch':'Godot'}</span></button>`;}cells+='<button class="day showcase" data-action="showcase"><strong>31 ✦</strong><span>Showcase</span></button>';
 return `${state.school?'<div class="school-banner">Shared-computer mode: guest drafts are temporary. Download a project before leaving.</div>':''}<div class="intro"><div><div class="eyebrow">${p.name} · ${p.time}</div><h1>Your October quest book</h1><p>${count} of 30 quests completed. Start anywhere, revisit a favorite, or take a catch-up day.</p><div class="progress-track" aria-label="${count} of 30 complete"><span style="width:${count/30*100}%"></span></div></div><button data-action="choose">Change learning path</button></div>${themeCards()}<div class="toolbar"><button class="primary" data-action="day" data-value="${state.lastDays[state.path]||1}">Continue your quest</button><button data-action="local-settings">Guest & device settings</button></div><section class="calendar-wrap"><h2>October 2026</h2><div class="calendar">${['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map(s=>`<div class="weekday">${s}</div>`).join('')}${cells}</div></section><p class="meta" style="margin-top:15px">Thirty quests, one showcase. Dates guide your month; they never lock lessons. Take the time you need.</p>`;}
function lessonHTML(){const l=lesson(),p=project(),checks=state.checks[l.id]||[];editorTab=p.mode;const external=l.mode!=='browser';return `<div class="topline"><button data-action="month">October calendar</button><span class="pill">${pathInfo().name}</span><span class="meta">Quest ${activeDay} · ${pathInfo().time}</span></div><div class="lesson-head"><div><div class="eyebrow">${themeIntro()}</div><h1>${esc(l.title)}</h1></div><span class="pill">${l.mode==='browser'?'Build on this site':l.mode==='scratch'?'Build in Scratch':'Build in Godot'}</span></div>${themeCards()}${external?`<div class="help-note">Your main project today is in <b>${l.mode==='scratch'?'Scratch':'Godot'}</b>. The browser lab stays available for practice. It does not automatically turn into a ${l.mode==='scratch'?'Scratch':'Godot'} project.</div>`:''}<div class="view-tabs" role="tablist" aria-label="Workspace panels">${['lesson','build','play'].map(t=>`<button role="tab" aria-selected="${mobileView===t}" data-action="mobile-view" data-value="${t}">${{lesson:'Quest',build:'Build',play:'Play'}[t]}</button>`).join('')}</div><div class="workspace" data-view="${mobileView}"><section class="panel lesson-panel"><h2>Your quest</h2><div class="concept">${esc(l.concept)}</div><div class="steps">${l.steps.map((step,i)=>`<div class="step"><input type="checkbox" id="step-${i}" data-step="${i}" ${checks[i]?'checked':''}><label for="step-${i}">${esc(step)}</label></div>`).join('')}</div><details><summary>Need a hint?</summary><p>${esc(l.hint)}</p></details><details><summary>Extra challenge</summary><p>${esc(l.challenge)}</p></details><details><summary>Walk through this activity</summary><ol class="guide-steps">${(l.walkthrough||[]).map(t=>`<li>${esc(t)}</li>`).join('')}</ol></details><div class="help-note"><b>Check your result:</b> ${esc(l.success||l.recall)}</div>${l.reference?`<h3>GDScript comparison</h3><p class="meta">Read this example here; it runs in Godot, not the browser lab.</p><pre class="guide-code">${esc(l.reference)}</pre>`:''}<h3>Tell someone</h3><p>${esc(l.recall)}</p><label for="quest-note">Optional note</label><textarea id="quest-note" rows="2" maxlength="400" placeholder="What did you discover?">${esc(state.notes[l.id]||'')}</textarea><div class="complete-box"><label><input type="checkbox" id="explained" ${checks[3]?'checked':''}>I explained or showed what I learned.</label><button class="primary" id="complete" data-action="complete" ${checks.slice(0,4).filter(Boolean).length===4?'':'disabled'}>${state.completed[l.id]?'Quest completed ✓':'Complete this quest'}</button><p class="meta" style="margin:8px 0 0">${external?'Complete the steps in your external tool first.':'Try the steps, then explain your result.'}</p></div>${external?'<button style="margin-top:12px;width:100%" data-action="tool-guide">Open the tool guide</button>':''}<div class="resources">${l.resources.map(r=>r.url.startsWith('#')?'<button data-action="help">Builder guide</button>':`<a href="${r.url}" target="_blank" rel="noopener">${esc(r.label)}</a>`).join('')}</div></section><section class="panel build-panel"><h2>${external?'Practice lab':'Build your creation'}</h2><div class="settings-grid"><div><label for="scene-select">Scene</label><select id="scene-select">${[0,1].map(n=>`<option value="${n}" ${p.scene===n?'selected':''}>Scene ${n+1}</option>`).join('')}</select></div><div><label for="trigger">Start when</label><select id="trigger">${[['start','Run is pressed'],['tap','Character is tapped'],['message','Message arrives'],['controls','Direction controls']].map(([v,t])=>`<option value="${v}" ${p.scenes[p.scene].trigger===v?'selected':''}>${t}</option>`).join('')}</select></div></div><div class="editor-tabs" role="tablist" aria-label="Coding interface"><button role="tab" data-action="editor-mode" data-value="blocks" aria-selected="${p.mode==='blocks'}">Picture blocks</button><button role="tab" data-action="editor-mode" data-value="code" aria-selected="${p.mode==='code'}">Type commands</button></div><div id="editor">${editorHTML()}</div><div class="toolbar"><button data-action="starter">Try the lesson example</button>${l.practice?'<button data-action="practice">Load practice stage</button>':''}<button data-action="clear-program">Clear commands</button></div><details><summary>Scene settings</summary><div class="settings-grid"><div><label for="target">Treasure target</label><input id="target" type="number" min="1" max="20" value="${p.target}"></div><div><label for="speed">Movement speed</label><input id="speed" type="number" min="1" max="10" value="${p.speed}"></div><div><label for="character-1">Companion 1</label><select id="character-1">${characterOptions(p.scenes[p.scene].players[0].avatar)}</select></div><div><label for="character-2">Companion 2</label><select id="character-2">${characterOptions(p.scenes[p.scene].players[1].avatar)}</select></div></div><label class="radio-row" style="margin-top:12px"><input id="sound" type="checkbox" ${p.sound?'checked':''}>Sound effects</label></details><p class="status" id="save-status">${user?'Online saving enabled':'Guest draft · '+(state.keep?'kept on this device':'temporary session')}</p></section><section class="panel stage-panel"><div class="stats"><span id="score">Score 0 / ${p.target}</span><span id="stage-scene">Scene ${p.scene+1}</span></div><div class="stage-frame"><canvas id="stage" aria-label="Interactive game stage. Use Run, direction buttons, or Layout controls." tabindex="0"></canvas></div><div class="stage-controls"><button class="primary" data-action="run">▶ Run</button><button data-action="stop">Stop</button><button data-action="reset">Reset</button></div><div id="run-status" class="status" role="status" aria-live="polite">Ready. Press Run.</div><div class="direction-pad" aria-label="Direction controls"><button class="up" data-direction="up" aria-label="Move up">↑</button><button class="left" data-direction="left" aria-label="Move left">←</button><button class="down" data-direction="down" aria-label="Move down">↓</button><button class="right" data-direction="right" aria-label="Move right">→</button></div><details><summary>Arrange the stage</summary><label for="layout-tool">Tap the stage to place</label><select id="layout-tool"><option value="">Play mode</option><option value="player1">Companion 1</option><option value="player2">Companion 2</option><option value="treasure">Treasure</option><option value="hazard">Hazard</option><option value="erase">Erase treasure or hazard</option></select><p class="layout-note">Choose an item, then tap where it belongs. Switch back to Play mode before running.</p></details><div class="project-bar"><input id="project-title" aria-label="Project title" value="${esc(p.title)}" maxlength="80"><button data-action="download">Download project</button><button data-action="import">Open project</button></div><div class="toolbar"><button data-action="local-settings">Saving options</button>${user?'<button data-action="save-now">Save online now</button><button data-action="load-online">Load online version</button>':''}</div></section></div>${external?`<section class="panel external-panel"><h2>${l.mode==='scratch'?'Scratch':'Godot'} build guide</h2>${toolGuide(l)}</section>`:''}<div class="finish-nav"><button data-action="day" data-value="${Math.max(1,activeDay-1)}" ${activeDay===1?'disabled':''}>Previous quest</button><button class="secondary" data-action="${activeDay===30?'showcase':'day'}" data-value="${activeDay+1}">${activeDay===30?'October showcase':'Next quest'}</button></div>`;}
function characterOptions(selected){return `<option value="" ${selected===null?'selected':''}>Theme companion</option>`+avatarNames.map((n,i)=>`<option value="${i}" ${selected===i?'selected':''}>${n}</option>`).join('');}
const blockLabels={right:'Move right',left:'Move left',up:'Move up',down:'Move down',say:'Say',wait:'Wait',repeat:'Repeat move',sound:'Play sound',hide:'Hide',show:'Show',next:'Next scene',message:'Send message',ifwin:'If score reaches target, say'};
function editorHTML(){const p=project(),s=p.scenes[p.scene];if(p.mode==='code')return `<p class="code-warning">Teaching commands for this lab. This is not JavaScript or GDScript.</p><textarea id="code" class="code-area" maxlength="5000" spellcheck="false" aria-label="Practice code">${esc(s.code)}</textarea><details><summary>Command reference</summary><pre class="command-ref">move right 2
move up 1
repeat 3 right 1
say "Hello!"
wait 1
speed 3
target 3
ifwin "You win!"
sound
next
message
hide
show
# This is a comment</pre></details>`;
return `<p class="meta">Tap a command to add it. Use Earlier / Later to change its order.</p><div class="palette">${PQC.OPS.map(op=>`<button data-action="add-block" data-value="${op}">${esc(blockLabels[op])}</button>`).join('')}</div><div class="block-list" aria-label="Your program">${s.program.length?s.program.map(blockHTML).join(''):'<p class="muted">Your program is empty. Add a command above.</p>'}</div>`;}
function blockHTML(b,i){const numeric=['right','left','up','down','wait','repeat'].includes(b.op);return `<div class="block" data-op="${b.op}" data-index="${i}"><span class="label">${blockLabels[b.op]}</span>${numeric?`<input type="number" min="0" max="20" step="${b.op==='wait'?'0.5':'1'}" value="${b.value}" data-block-field="value" aria-label="${blockLabels[b.op]} amount">`:['say','ifwin'].includes(b.op)?`<input type="text" value="${esc(b.value)}" maxlength="100" data-block-field="value" aria-label="Speech text">`:''}${b.op==='repeat'?`<select data-block-field="direction" aria-label="Repeat direction">${['right','left','up','down'].map(x=>`<option ${b.direction===x?'selected':''}>${x}</option>`).join('')}</select><label>count <input type="number" min="1" max="10" value="${b.count}" data-block-field="count" aria-label="Repeat count"></label>`:''}${!['next','message'].includes(b.op)?`<select data-block-field="target" aria-label="Character for command"><option value="1" ${b.target===1?'selected':''}>Companion 1</option><option value="2" ${b.target===2?'selected':''}>Companion 2</option></select>`:''}<div class="block-tools"><button data-action="earlier" data-index="${i}" aria-label="Move command earlier" ${i===0?'disabled':''}>Earlier</button><button data-action="later" data-index="${i}" aria-label="Move command later">Later</button><button data-action="remove-block" data-index="${i}" aria-label="Remove command">×</button></div></div>`;}
function mountLesson(){stage=new PQC.Stage($('#stage'),project(),r=>{const el=$('#run-status');if(el){el.textContent=r.text;el.className='status'+(r.error?' error':'');$('#score').textContent=`Score ${r.score} / ${r.target}`;$('#stage-scene').textContent=`Scene ${r.scene+1}`;if($('#scene-select')&&+$('#scene-select').value!==r.scene){$('#scene-select').value=r.scene;$('#trigger').value=project().scenes[r.scene].trigger;$('#editor').innerHTML=editorHTML();persist();}}});stage.onEdit=()=>persist();}
function refreshEditor(){stage?.stop();$('#editor').innerHTML=editorHTML();persist();}
function codeSample(l){if(l.guideCode)return l.guideCode;if(l.path==='dev'){
 if(l.day<=10)return `extends CharacterBody2D\n\n@export var speed: float = 220.0\n\nfunc _physics_process(_delta):\n    var direction = Input.get_vector(\n        "move_left", "move_right", "move_up", "move_down")\n    velocity = direction * speed\n    move_and_slide()`;
 if(l.day<=13)return `extends Area2D\n\nsignal collected\n\nfunc _on_body_entered(body):\n    if body is CharacterBody2D:\n        collected.emit()\n        queue_free()\n\n# Connect body_entered to _on_body_entered.\n# In Main, connect treasure.collected to your score function.`;
 return `# In Main (Node2D):\nvar score := 0\nvar target := 5\nvar playing := true\n\nfunc add_score():\n    if not playing:\n        return\n    score += 1\n    $CanvasLayer/Score.text = str(score)\n    if score >= target:\n        playing = false\n        $CanvasLayer/Message.text = "You win!"\n\nfunc restart():\n    get_tree().reload_current_scene()`;
 }return `Player sprite:\nwhen green flag clicked\ngo to x: -150 y: 0\nforever\n  if <key [right arrow] pressed?> then\n    change x by 4\n\nTreasure sprite:\nwhen green flag clicked\nshow\nwait until <touching [Player]?>\nchange [score] by 1\nhide\n\nStage:\nwhen green flag clicked\nset [score] to 0\nwait until <score = 5>\nbroadcast [Win]`;
}
function toolGuide(l){const godot=l.mode==='godot';const theme=PQC.THEMES[state.theme];let steps;
 if(l.walkthrough?.length){steps=l.walkthrough;}
 else if(godot){steps=[`Use Godot 4 Standard with GDScript. Create or open your project; use the Compatibility renderer for this small 2D game.`,`For movement, select Player (CharacterBody2D), attach a script, and add move_left, move_right, move_up and move_down in Project Settings → Input Map. Bind arrow/WASD keys and controller directions.`,`For pickups, create an Area2D scene with art and CollisionShape2D. In the Node/Signals panel connect body_entered to its script. Set collision layers/masks so the Player body can be detected.`,`For score, create CanvasLayer → Score (Label) and Message (Label) under Main. Connect each treasure's collected signal to add_score in Main. Node names in scripts must match exactly.`,`For today's quest, follow the three steps above. Run the main scene with F6 for the current scene or F5 for the project. Save scenes/scripts and keep a copy of the source folder.`,`Use ${theme.name} art and ${theme.treasure} in your game. You can download the original background below. Start with simple shapes for characters; art can come later.`];}
 else{steps=[`Open Scratch Create on a compatible browser. Choose or draw a player and rename it Player; choose a ${theme.name.toLowerCase()} setting.`,`Open the Code tab. Drag an Events block (when green flag clicked) into the script area. Add Motion blocks under it; attach control blocks around actions to make loops and decisions.`,`For treasure, add a second sprite, name it Treasure and use ${theme.treasure} as your art. Create score under Variables and choose For all sprites.`,`Use the block recipe below as a starting pattern. It is a readable recipe, not text you paste into Scratch. Find each corresponding colored block in its category.`,`Follow today's three quest steps. Use the green flag to test start, pickup, win and replay. Keep the browser lab for comparison if needed.`,`Save using File → Save to your computer. Reopen the .sb3 file to check it. Public sharing and a Scratch account are not required for saving a local project.`];}
 return `<p class="muted">Use this guide alongside today's quest. Build one part, run it, then add the next part.</p><ol class="guide-steps">${steps.map(s=>`<li>${esc(s)}</li>`).join('')}</ol><h3>${godot?'GDScript reference: '+esc(l.guideFile||'script'):'Scratch block recipe'}</h3><p class="meta">${godot?'Use this script with the node types and names described above. Later features appear only in later lesson examples; the downloadable project includes the full reference.':'Each indented line belongs inside the block above it.'}</p><pre class="guide-code">${esc(codeSample(l))}</pre>${godot&&l.guideFile!=='Main.gd'&&l.day>=12?`<details><summary>Main.gd for this checkpoint</summary><pre class="guide-code">${esc(l.guideMain)}</pre></details>`:''}${godot&&l.day>=10?androidGuide():''}<h3>If something goes wrong</h3><p>${godot?'Read the first error and its line number. Check indentation, node names, input action names and whether the script extends the right node type. For missed pickups, check shape sizes and collision layers/masks.':'Check that blocks are attached, the right sprite is selected and variable names match. Put show and score reset under the green flag. If a pickup counts repeatedly, hide it or wait until contact ends.'}</p><div class="resources">${l.resources.map(r=>`<a href="${r.url}" target="_blank" rel="noopener">${r.label}</a>`).join('')}<a href="${theme.file}" download="${state.theme}-background.webp">Download ${theme.name} background</a>${godot&&!window.PQC_OFFLINE?'<a href="starter-godot.zip" download>Download optional Godot reference project</a>':''}${l.checkpoint&&!window.PQC_OFFLINE?`<a href="${esc(l.checkpoint)}" download>Download this lesson’s Scratch checkpoint</a>`:''}</div><p class="meta">External websites may need permission in Amazon Kids or at school. Downloads depend on browser/school policy.</p>`;}
function androidGuide(){return `<details><summary>Grown-up guide: test on the Retroid</summary><ol class="guide-steps"><li>First make the game work on the computer. Retroid Pocket 5 runs Android; it needs an Android APK, not a flashed cartridge.</li><li>Install Godot export templates through Editor → Manage Export Templates. Follow the current Android export guide linked below for Java and Android SDK requirements.</li><li>Set Java SDK Path and Android SDK Path in Godot's Editor Settings. In Project Settings, search ETC2 and enable Import ETC2 ASTC. Add an Android preset under Project → Export and choose a unique package name.</li><li>With an adult, export a test APK and transfer it to the Retroid. Permit installation from the transfer source only as needed, then install the APK.</li><li>Test every controller direction/button, readable text, restart and performance on the real handheld. Debug export is for your test device; store publication is a separate process.</li><li>Keep the editable Godot project and any signing keys backed up. The website does not install or flash the game for you.</li></ol></details>`;}
function helpHTML(){return `<div class="intro"><div><div class="eyebrow">Your creator's toolkit</div><h1>A little help, right here</h1><p class="muted">Try one small change. Watch what happens. Explain it in your own words.</p></div><button data-action="month">Back to October</button></div><div class="help-grid"><section class="panel" id="help-builder"><h2>Browser builder</h2><details open><summary>Start and run</summary><p>Add commands from the toolbox. They run from top to bottom. Earlier / Later changes their order; × removes a command. Run starts from the saved layout, and Reset restores it.</p></details><details><summary>Tap events and direction controls</summary><p>Choose Character is tapped, press Run, then tap Companion 1. Choose Direction controls to play with on-screen buttons or arrow keys. Run any setup commands first.</p></details><details><summary>Scenes and messages</summary><p>Each scene has its own program and layout. Next scene starts the other scene. Send message starts the other scene only if its trigger is Message arrives. Avoid scenes that endlessly send each other messages.</p></details><details><summary>Repeat, score and conditions</summary><p>Repeat move has a direction, distance and count. Score increases when Companion 1 touches a treasure. If score reaches target, say only speaks when enough treasures have been collected.</p></details><details><summary>Changing the stage</summary><p>Open Arrange the stage, choose an item and tap its position. Use Erase to remove a treasure or hazard. Choose Play mode again before running. Character choices are under Scene settings.</p></details><details><summary>Typing</summary><p>The lab uses a limited teaching language. Open Type commands for examples. It is not GDScript or JavaScript. The two editor modes keep separate programs, so switching modes does not convert code.</p></details></section><section class="panel"><h2>Save your work</h2><p>Guests can choose a temporary session or keep a draft on a personal device. Clearing browser storage can erase local drafts. Download a project file for a backup.</p><p>A saved child account syncs website progress and browser projects online. Scratch and Godot files have their own save systems.</p><button data-action="local-settings">Guest saving options</button><details><summary>Two devices edited the same project</summary><p>If a newer online version exists, we stop automatic saving. Download your current draft, then choose Load online version. You can open either project file later.</p></details></section><section class="panel"><h2>Choose the right path</h2><p><b>Story Makers:</b> picture blocks and interactive stories, suggested ages 6–7.</p><p><b>Game Makers:</b> scores, choices and Scratch games, suggested ages 8–10.</p><p><b>Game Developers:</b> typed-code practice, Godot and handheld games, suggested ages 11+ or ready beginners.</p><p>Change paths any time; each path keeps its own progress and project. You don't need to give your age.</p><button data-action="choose">Choose a path</button></section><section class="panel"><h2>Other tools</h2><p>Godot runs on the computer for this course. The tablet can show instructions and let you practice concepts. Scratch needs a compatible browser; Fire's browser must be tested.</p><div class="resources"><a href="https://scratch.mit.edu/ideas" target="_blank" rel="noopener">Scratch tutorials</a><a href="https://docs.godotengine.org/en/stable/getting_started/step_by_step/index.html" target="_blank" rel="noopener">Godot basics</a><a href="https://docs.godotengine.org/en/stable/tutorials/export/exporting_for_android.html" target="_blank" rel="noopener">Android export</a></div><p class="meta" style="margin-top:12px">References are linked, not copied in full. No ChatGPT use is required.</p></section></div>`;}
function showcaseHTML(){return `<div class="eyebrow">October 31 · Family showcase</div><h1>You made something of your own.</h1><div class="page-layout"><section class="panel"><img class="asset-preview" src="${PQC.THEMES[state.theme].file}" alt="${PQC.THEMES[state.theme].name} landscape"><h2 style="margin-top:15px">${pathInfo().name} showcase</h2><p class="badge">✦ ${completedCount()} quests explored and completed</p><ol class="guide-steps"><li>Show your creation to someone.</li><li>Explain a sequence, event or rule.</li><li>Describe one mistake you fixed.</li><li>Change something without following a recipe.</li><li>Save the editable project, not only a screenshot.</li></ol><div class="toolbar"><button class="primary" data-action="day" data-value="30">Open my final quest</button><button data-action="download">Download browser project</button></div></section><section class="panel"><h2>Ready for another path?</h2><p>From Story Makers: show a sequence, event and repeat you understand. Try making a score and a condition in Game Makers.</p><p>From Game Makers: explain a loop, variable and condition, then rebuild one familiar action in Godot. Learning a new tool doesn't erase what you know.</p><p>You can also stay on your current path and make a more interesting creation next month.</p><button data-action="choose">Explore the paths</button><p class="meta" style="margin-top:14px">November's club lessons are planned but not built in this October edition.</p></section></div>`;}
function parentsHTML(){return `<div class="eyebrow">Grown-up corner</div><h1>Help them become independent creators.</h1>${user?.role==='parent'?`<div class="toolbar"><button class="primary" data-action="new-child">Add a child account</button><button data-action="logout">Sign out</button></div><section class="panel"><h2>Your children's progress</h2><div class="parent-children" id="children"><p>Loading accounts…</p></div></section>`:`<section class="panel"><h2>Manage your family</h2><p>Create a grown-up account to add children, view their October progress and reset forgotten codes. Children use generated club usernames and six-digit codes.</p><div class="toolbar"><button class="primary" data-action="parent-register">Create grown-up account</button><button data-action="account">Sign in</button></div></section>`}<div class="help-grid" style="margin-top:20px"><section class="panel"><h2>Keep sessions small</h2><p>Story Makers: 10–15 minutes. Game Makers: 20–30 minutes. Game Developers: 30–45 minutes. Dates are suggestions, not deadlines.</p><p>Ask what they predict, what changed and why. Offer a hint before taking over. They can explain aloud instead of writing a note.</p></section><section class="panel"><h2>Devices and school</h2><p>Test your real Fire tablets: Run, sound, typing, turning the tablet, saving and reopening. Approve this website in Amazon Kids; external links need separate permission.</p><p>For shared school computers use temporary guest mode, download work if permitted and sign out of saved accounts. School access depends on school policy.</p><button data-action="local-settings">Shared-device options</button></section></div>`;}
async function loadChildren(){try{const r=await api('children');const el=$('#children');if(!el)return;el.innerHTML=r.children.length?r.children.map(c=>`<div class="child-row">${avatar(c.avatar,46)} <b>${esc(c.username)}</b><p class="meta">${Object.keys(c.progress).filter(k=>c.progress[k]).length} quests completed across all paths</p><div class="toolbar"><button data-action="reset-child" data-id="${c.id}">Reset code</button><button class="danger" data-action="delete-child" data-id="${c.id}">Delete account</button></div></div>`).join(''):'<p>Add your first child account. Keep their username, code and recovery key somewhere safe.</p>';fitAvatars();}catch(e){if($('#children'))$('#children').textContent=e.message;}}
function modal(title,content){$('#dialog-content').innerHTML=`<div class="dialog-heading"><h2>${esc(title)}</h2><button data-action="close-dialog" aria-label="Close dialog">×</button></div>${content}`;$('#dialog').showModal();fitAvatars();}
function showAccount(){if(user){modal('Your account',`<p>Signed in as <b>${esc(user.username)}</b>.</p><p>Website drafts and progress save online for child accounts. Download your project before signing out of a shared computer.</p><div class="toolbar"><button data-action="logout">Sign out</button>${user.role==='parent'?'<button data-action="parents">Family dashboard</button>':!user.parent_id?'<button data-action="link-parent">Connect a grown-up account</button>':''}</div>`);return;}
 modal('Sign in',`<p>Guests can keep creating without signing in.</p><form id="login-form" class="form-grid"><div><label for="login-name">Club username</label><input id="login-name" name="username" autocomplete="username" required maxlength="40"></div><div><label for="login-secret">Child code or grown-up password</label><input id="login-secret" name="secret" type="password" autocomplete="current-password" required maxlength="128"></div><label class="check"><input type="checkbox" name="remember">Remember sign-in on my personal device</label><p class="meta">Leave this off on a school or shared computer.</p><p class="error-msg" id="form-error"></p><button class="primary">Sign in</button></form><div class="toolbar"><button data-action="recover">Forgot code or password</button><button data-action="parent-register">Grown-up setup</button>${sessionConfig.openChildSignup?'<button data-action="child-register">Create unlinked child account</button>':''}</div>`);}
function registerForm(child=false){if(window.PQC_OFFLINE)return toast('Account setup is available in the hosted edition. Guest lessons work here.');modal(child?'Create a saved account':'Grown-up setup',`<p>${child?'Choose a six-digit code. A club username will be assigned. Keep the recovery key if you do not connect a grown-up.':'Choose your own grown-up username and password. Children never need your password to learn.'}</p><form id="register-form" data-role="${child?'child':'parent'}" class="form-grid">${child?'':'<div><label for="register-name">Grown-up username</label><input id="register-name" name="username" pattern="[a-zA-Z0-9-]{3,40}" required autocomplete="username"></div>'}<div><label for="register-secret">${child?'Six-digit code':'Password (at least 10 characters)'}</label><input id="register-secret" name="secret" type="password" ${child?'pattern="[0-9]{6}" inputmode="numeric" maxlength="6"':'minlength="10" maxlength="128"'} required autocomplete="new-password"></div>${!child&&sessionConfig.inviteRequired?'<div><label for="invite">Family setup code</label><input id="invite" name="invite" type="password" required></div>':''}<p class="error-msg" id="form-error"></p><button class="primary">Create account</button></form><p class="meta">No child real name, birth date or email is needed. Registration is for saved progress; guest lessons remain open.</p>`);}
function localSettings(){modal('Guest & device saving',`<p>On a shared or school computer, leave personal-device saving off.</p><h3>Your avatar</h3><div class="avatar-grid">${avatarNames.map((n,i)=>`<button type="button" class="${state.avatar===i?'selected':''}" data-action="profile-avatar" data-value="${i}" aria-label="${n}">${avatar(i,65)}</button>`).join('')}</div><label class="radio-row"><input id="keep-local" type="checkbox" ${state.keep?'checked':''}>Keep guest progress on this personal device</label><label class="radio-row"><input id="school-mode" type="checkbox" ${state.school?'checked':''}>Shared-computer mode: temporary guest drafts</label><p class="meta">Temporary drafts are lost when leaving the session. Personal drafts can be erased when browser storage is cleared. Downloads provide a backup.</p><div class="toolbar"><button data-action="apply-local" class="primary">Apply choices</button><button data-action="download">Download project backup</button><button class="danger" data-action="clear-guest">Clear guest progress here</button></div>`);}
function downloadProject(){if(!state.path)return toast('Choose a learning path first.');download(JSON.stringify(project(),null,2),project().title.replace(/[^a-z0-9-]/gi,'-')+'.pqc.json','application/json');}
function download(text,name,type){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function importProject(){const input=document.createElement('input');input.type='file';input.accept='.json,.pqc.json';input.onchange=async()=>{try{const f=input.files[0];if(!f)return;if(f.size>200000)throw Error('Choose a project under 200 KB.');const p=PQC.validateProject(JSON.parse(await f.text()));if(!confirm('Replace this path’s browser project? Download it first if you want to keep both.'))return;state.projects[state.path]=p;state.theme=p.theme;persist();render();toast('Project opened.');}catch(e){toast(e.message);}};input.click();}
function checkComplete(){const l=lesson(),checks=state.checks[l.id]||[];$('#complete').disabled=checks.slice(0,4).filter(Boolean).length!==4;persist();}
function updateSetting(){stage?.reset();persist();}
async function adoptUser(r){user=r.user;revision=0;savingConflict=false;dirty=false;clearTimeout(saveTimer);let saved;try{saved=await api('save');}catch{}
 if(saved?.payload){state={...state,...saved.payload};revision=saved.revision;}else{state={schema:1,path:user.path,theme:user.theme,avatar:user.avatar,completed:{},checks:{},notes:{},projects:{},lastDays:{},keep:false,school:false};}
 if(user.role==='parent'){view='parents';}else view=state.path?'month':'choose';$('#dialog').close();render();}
async function handleAction(action,value,button){
 if(action==='close-dialog')return $('#dialog').close();
 if(['month','choose','help','parents','showcase'].includes(action)){if($('#dialog').open)$('#dialog').close();view=action==='month'&&!state.path?'choose':action;if(action==='showcase'&&!state.path)view='choose';render();return;}
 if(action==='path'){state.path=value;activeDay=state.lastDays[value]||1;view='month';persist();render();return;}
 if(action==='theme'){state.theme=value;if(state.path)project().theme=value;persist();render();return;}
 if(action==='day'){activeDay=+value;state.lastDays[state.path]=activeDay;view='lesson';persist();render();return;}
 if(action==='mobile-view'){mobileView=value;$('.workspace').dataset.view=value;document.querySelectorAll('.view-tabs [role=tab]').forEach(b=>b.setAttribute('aria-selected',b.dataset.value===value));return;}
 if(action==='editor-mode'){project().mode=value;persist();render();return;}
 if(action==='add-block'){const s=project().scenes[project().scene];if(s.program.length>=80)return toast('Keep programs below 80 commands.');s.program.push({op:value,value:['say','ifwin'].includes(value)?'Hello!':['sound','hide','show','next','message'].includes(value)?0:1,target:1,...(value==='repeat'?{count:3,direction:'right'}:{})});refreshEditor();$('.block-list')?.scrollTo(0,$('.block-list').scrollHeight);return;}
 if(['earlier','later','remove-block'].includes(action)){const p=project().scenes[project().scene].program,i=+button.dataset.index;if(action==='remove-block')p.splice(i,1);else{const j=i+(action==='earlier'?-1:1);if(j>=0&&j<p.length)[p[i],p[j]]=[p[j],p[i]];}refreshEditor();return;}
 if(action==='practice'){if(!confirm('Replace this path’s browser project with the lesson practice stage? Download your creation first if you want to keep it.'))return;const p=structuredClone(lesson().practice);p.theme=state.theme;state.projects[state.path]=p;persist();render();return;}
 if(action==='starter'){if(!confirm('Replace the current scene’s commands with the lesson example? Your layout stays.'))return;const s=project().scenes[project().scene];s.program=typeof structuredClone!=='undefined'?structuredClone(lesson().starter):JSON.parse(JSON.stringify(lesson().starter));s.code=lesson().starterCode||'move right 2\nsay "Hello!"';refreshEditor();return;}
 if(action==='clear-program'){if(confirm('Clear this scene’s commands?')){const s=project().scenes[project().scene];s.program=[];s.code='';refreshEditor();}return;}
 if(action==='run'){stage.layout=null;$('#layout-tool').value='';if(window.innerWidth<=700){mobileView='play';$('.workspace').dataset.view='play';document.querySelectorAll('.view-tabs [role=tab]').forEach(b=>b.setAttribute('aria-selected',b.dataset.value==='play'));}try{PQC.validateProject(project());await stage.run();}catch(e){stage.report(e.message,true);stage.stop();}persist();return;}
 if(action==='stop'){stage.stop();stage.report('Stopped. Your commands and layout are unchanged.');return;}
 if(action==='reset'){stage.reset();$('#scene-select').value=project().scene;return;}
 if(action==='complete'){state.completed[lesson().id]=true;persist();$('#complete').textContent='Quest completed ✓';toast('Quest completed! You can revisit it any time.');return;}
 if(action==='download')return downloadProject();if(action==='import'){if(!state.path)return toast('Choose a learning path first.');return importProject();}
 if(action==='account')return showAccount();if(action==='parent-register')return registerForm(false);if(action==='child-register')return registerForm(true);
 if(action==='local-settings')return localSettings();if(action==='profile-avatar'){state.avatar=+value;persist();document.querySelectorAll('.avatar-grid button').forEach(b=>b.classList.toggle('selected',+b.dataset.value===state.avatar));return;}
 if(action==='apply-local'){state.school=$('#school-mode').checked;state.keep=$('#keep-local').checked&&!state.school;if(!state.keep)try{localStorage.removeItem('pqc-guest');}catch{}persist();$('#dialog').close();render();toast('Saving choices updated.');return;}
 if(action==='clear-guest'){if(user)return toast('Sign out before clearing guest data.');if(confirm('Clear all guest progress and browser creations on this device?')){try{sessionStorage.removeItem('pqc-guest');localStorage.removeItem('pqc-guest');}catch{}state={schema:1,path:null,theme:'royal',avatar:0,completed:{},checks:{},notes:{},projects:{},lastDays:{},keep:false,school:true};view='choose';$('#dialog').close();render();}return;}
 if(action==='save-now')return saveOnline();
 if(action==='load-online'){if(confirm('Load the latest online progress and projects? Download your local project first if you want to keep it.')){clearTimeout(saveTimer);const r=await api('save');if(r.payload){state=r.payload;revision=r.revision;savingConflict=false;dirty=false;keepChildDraft();render();toast('Loaded online version.');}}return;}
 if(action==='tool-guide'){modal('Your tool guide',toolGuide(lesson()));return;}
 if(action==='privacy'){modal('Privacy & saving',`<p>Guest mode needs no name, age, email or online account. Personal-device saving uses your browser storage only. Shared-computer guest mode keeps work temporarily in memory.</p><p>Saved accounts store a club username, avatar choice, learning path, completed quests and small browser projects on the club server. Codes/passwords are stored as protected hashes. No advertisements, third-party analytics, chat or public child directory are included.</p><p>Grown-ups can reset or delete their children's accounts. Recovery uses a private recovery key or the connected parent account; there is no email reset service in this edition.</p><p>Scratch and Godot are separate tools with their own policies and save systems. Server hosting creates ordinary operational connections; the owner should publish their contact and retention policy before outside saved enrollment.</p>`);return;}
 if(action==='recover'){modal('Recover an account',`<p>Use the private recovery key kept at setup, or ask your connected grown-up to reset your child code.</p><form id="recover-form" class="form-grid"><label>Club username<input name="username" required autocomplete="username"></label><label>Recovery key<input name="recoveryKey" required type="password"></label><label>New child code or grown-up password<input name="secret" required type="password" maxlength="128"></label><p class="error-msg" id="form-error"></p><button class="primary">Reset access</button></form><p class="meta">Without a recovery key or linked grown-up, we cannot identify an account from its avatar. You can keep learning as a guest.</p>`);return;}
 if(action==='logout'){if(dirty&&user?.role==='child')await saveOnline();if(dirty&&!confirm('Your latest draft is not synced. Download it before signing out if you want to keep it. Sign out anyway?'))return;await api('logout',{});clearTimeout(saveTimer);try{sessionStorage.removeItem('pqc-'+user.id);}catch{}user=null;dirty=false;savingConflict=false;revision=0;state={schema:1,path:null,theme:'royal',avatar:0,completed:{},checks:{},notes:{},projects:{},lastDays:{},keep:false,school:true};view='choose';$('#dialog').close();render();return;}
 if(action==='new-child'){childAvatar=0;modal('Add a child',`<p>A unique club username will be assigned. No real name or birthday needed.</p><form id="child-form" class="form-grid"><label>Six-digit child code<input name="secret" type="password" inputmode="numeric" pattern="[0-9]{6}" maxlength="6" required></label><label>Learning path<select name="path">${Object.entries(curriculum.paths).map(([k,p])=>`<option value="${k}">${p.name} · ${p.ages}</option>`).join('')}</select></label><label>Theme<select name="theme">${Object.entries(PQC.THEMES).map(([k,t])=>`<option value="${k}">${t.name}</option>`).join('')}</select></label><div><label>Choose an avatar</label><div class="avatar-grid">${avatarNames.map((n,i)=>`<button type="button" class="${i===0?'selected':''}" data-action="child-avatar" data-value="${i}" aria-label="${n}">${avatar(i,65)}</button>`).join('')}</div></div><p class="error-msg" id="form-error"></p><button class="primary">Create child account</button></form>`);return;}
 if(action==='child-avatar'){childAvatar=+value;document.querySelectorAll('.avatar-grid button').forEach(b=>b.classList.toggle('selected',+b.dataset.value===childAvatar));return;}
 if(action==='reset-child'){modal('Reset child code',`<form id="reset-form" data-id="${button.dataset.id}" class="form-grid"><label>New six-digit code<input name="secret" type="password" pattern="[0-9]{6}" inputmode="numeric" maxlength="6" required></label><p class="error-msg" id="form-error"></p><button class="primary">Reset code</button></form>`);return;}
 if(action==='delete-child'){if(confirm('Permanently delete this child account and its online progress/projects?')){await api('delete-child',{id:button.dataset.id});loadChildren();}return;}
 if(action==='link-parent'){modal('Connect a grown-up',`<p>Ask your grown-up to enter their own account details. They will then be able to see progress and reset your code.</p><form id="link-form" class="form-grid"><label>Grown-up username<input name="username" required autocomplete="username"></label><label>Grown-up password<input name="secret" type="password" required autocomplete="current-password"></label><p class="error-msg" id="form-error"></p><button class="primary">Connect account</button></form>`);return;}
}
document.addEventListener('click',e=>{if(e.target.closest('.brand')){e.preventDefault();view=state.path?'month':'choose';render();return;}const b=e.target.closest('[data-action]');if(b){e.preventDefault();handleAction(b.dataset.action,b.dataset.value,b).catch(err=>toast(err.message));}const dir=e.target.closest('[data-direction]');if(dir)stage?.control(dir.dataset.direction);});
document.addEventListener('input',e=>{const t=e.target;if(t.matches('[data-block-field]')){const b=project().scenes[project().scene].program[+t.closest('[data-index]').dataset.index],key=t.dataset.blockField;b[key]=key==='value'&&['say','ifwin'].includes(b.op)?t.value:['value','count','target'].includes(key)?+t.value:t.value;stage?.stop();persist();}if(t.id==='code'){project().scenes[project().scene].code=t.value;stage?.stop();persist();}if(t.id==='quest-note'){state.notes[lesson().id]=t.value;persist();}if(t.id==='project-title'){project().title=t.value;persist();}});
document.addEventListener('change',e=>{const t=e.target,p=state.path?project():null;if(t.matches('[data-step]')){(state.checks[lesson().id]??=[])[+t.dataset.step]=t.checked;checkComplete();}if(t.id==='explained'){(state.checks[lesson().id]??=[])[3]=t.checked;checkComplete();}if(t.id==='scene-select'){p.scene=+t.value;persist();render();}if(t.id==='trigger'){p.scenes[p.scene].trigger=t.value;updateSetting();}if(t.id==='layout-tool'){stage.stop();stage.layout=t.value||null;stage.reset();stage.layout=t.value||null;stage.report(stage.layout?'Tap the stage to arrange your scene.':'Ready. Press Run.');}if(t.id==='target'||t.id==='speed'){p[t.id]=Math.max(1,Math.min(t.id==='target'?20:10,Math.round(+t.value||1)));t.value=p[t.id];updateSetting();}if(t.id==='sound'){p.sound=t.checked;persist();}if(t.id==='character-1'||t.id==='character-2'){p.scenes[p.scene].players[+t.id.slice(-1)-1].avatar=t.value===''?null:+t.value;updateSetting();}});
document.addEventListener('keydown',e=>{if(['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName)||$('#dialog').open)return;const dir={ArrowUp:'up',ArrowDown:'down',ArrowLeft:'left',ArrowRight:'right'}[e.key];if(dir&&stage?.running&&stage.current().trigger==='controls'){e.preventDefault();stage.control(dir);}});
document.addEventListener('submit',async e=>{e.preventDefault();const f=e.target,b=Object.fromEntries(new FormData(f)),err=$('#form-error'),submit=f.querySelector('button[type=submit],button.primary');if(err)err.textContent='';if(submit)submit.disabled=true;
 try{
  if(f.id==='login-form'){b.remember=new FormData(f).has('remember');const r=await api('login',b);await adoptUser(r);}
  if(f.id==='register-form'){b.role=f.dataset.role;b.path=state.path||'story';b.theme=state.theme;b.avatar=state.avatar;const r=await api('register',b);await adoptUser(r);modal('Keep your recovery key',`<p>Username: <b>${esc(r.user.username)}</b></p><p>Keep this key privately. It can reset account access.</p><div class="recovery">${esc(r.recoveryKey)}</div><button data-action="close-dialog" class="primary" style="margin-top:14px">I have kept it safely</button>`);}
  if(f.id==='child-form'){b.avatar=childAvatar;const r=await api('children',b);modal('Child account ready',`<p>Club username: <b>${esc(r.child.username)}</b></p><p>Use that username and the six-digit code you chose. Your parent dashboard can reset the code.</p><p>Private recovery key:</p><div class="recovery">${esc(r.recoveryKey)}</div><button data-action="close-dialog" class="primary" style="margin-top:14px">Done</button>`);loadChildren();}
  if(f.id==='recover-form'){const r=await api('recover',b);modal('Access reset',`<p>${esc(r.message)}</p><p>Your previous recovery key no longer works. Keep the new one privately.</p><div class="recovery">${esc(r.recoveryKey)}</div><button data-action="account" class="primary" style="margin-top:14px">Sign in</button>`);}
  if(f.id==='reset-form'){await api('reset-child',{id:f.dataset.id,secret:b.secret});$('#dialog').close();toast('Code changed; old child sessions signed out.');loadChildren();}
  if(f.id==='link-form'){await api('link-parent',b);user.parent_id='linked';$('#dialog').close();toast('Grown-up connected.');}
 }catch(error){if(err)err.textContent=error.message;else toast(error.message);}finally{if(submit)submit.disabled=false;}
});
window.addEventListener('resize',()=>fitAvatars());
window.addEventListener('beforeunload',e=>{if(user&&dirty){e.preventDefault();e.returnValue='';}});
async function start(){try{if(window.PQC_BOOTSTRAP)curriculum=window.PQC_BOOTSTRAP;else{const r=await fetch('curriculum.json');curriculum=await r.json();}try{const cfg=await api('session');sessionConfig=cfg;user=cfg.user;}catch{}
 let saved=null;if(user?.role==='child'){const r=await api('save');saved=r.payload;revision=r.revision;let draft;try{draft=JSON.parse(sessionStorage.getItem('pqc-'+user.id)||'null');}catch{}if(draft?.dirty&&draft.payload?.schema===1){saved=draft.payload;dirty=true;savingConflict=draft.revision!==revision;revision=draft.revision;}}
 if(!user){try{saved=JSON.parse(sessionStorage.getItem('pqc-guest')||localStorage.getItem('pqc-guest')||'null');}catch{}}
 if(saved&&saved.schema===1){state={...state,...saved};for(const key of Object.keys(state.projects)){try{PQC.validateProject(state.projects[key]);}catch{delete state.projects[key];}}}
 else if(user?.role==='child'){state.path=user.path;state.theme=user.theme;state.avatar=user.avatar;}
 if(!curriculum.paths[state.path])state.path=null;if(!PQC.THEMES[state.theme])state.theme='royal';view=user?.role==='parent'?'parents':state.path?'month':'choose';render();if(dirty){toast(savingConflict?'Recovered your draft. Another device has newer online work; download this draft before loading online.':'Recovered your unsynced draft from this session.');if(!savingConflict)saveTimer=setTimeout(saveOnline,1000);}
 }catch(e){$('#main').innerHTML='<h1>Could not open the quest book.</h1><p>Refresh the page after checking your connection. Your saved work has not been erased.</p>';}}
start();
